CREATE TYPE "RecordStatus" AS ENUM ('ACTIVE','INACTIVE','ARCHIVED');
CREATE TYPE "OrganizationStatus" AS ENUM ('ACTIVE','SUSPENDED','ARCHIVED');
CREATE TYPE "LicenseType" AS ENUM ('MN_245D','MN_144G','MN_144A','MN_245I','OTHER');
CREATE TYPE "LicenseStatus" AS ENUM ('ACTIVE','PENDING','SUSPENDED','EXPIRED','ARCHIVED');
CREATE TABLE "Brand" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"slug" TEXT NOT NULL UNIQUE,"status" "RecordStatus" NOT NULL DEFAULT 'ACTIVE',"logoObjectKey" TEXT,"faviconObjectKey" TEXT,"primaryDomain" TEXT,"supportEmail" TEXT,"themeConfigJson" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Organization" ("id" TEXT PRIMARY KEY,"brandId" TEXT,"legalName" TEXT NOT NULL,"displayName" TEXT NOT NULL,"slug" TEXT NOT NULL UNIQUE,"status" "OrganizationStatus" NOT NULL DEFAULT 'ACTIVE',"timezone" TEXT NOT NULL DEFAULT 'America/Chicago',"defaultLanguage" TEXT,"phone" TEXT,"email" TEXT,"addressLine1" TEXT,"addressLine2" TEXT,"city" TEXT,"state" TEXT,"postalCode" TEXT,"country" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Organization_brandId_fkey" FOREIGN KEY ("brandId") REFERENCES "Brand"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "OrganizationLicense" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"licenseType" "LicenseType" NOT NULL,"licenseNumber" TEXT,"licenseStatus" "LicenseStatus" NOT NULL DEFAULT 'PENDING',"effectiveDate" DATE,"expirationDate" DATE,"issuingAuthority" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "OrganizationLicense_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "Program" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"name" TEXT NOT NULL,"code" TEXT,"programType" TEXT,"status" "RecordStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Program_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "Location" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"programId" TEXT,"name" TEXT NOT NULL,"locationType" TEXT,"addressLine1" TEXT,"addressLine2" TEXT,"city" TEXT,"state" TEXT,"postalCode" TEXT,"country" TEXT,"status" "RecordStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Location_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "Location_programId_fkey" FOREIGN KEY ("programId") REFERENCES "Program"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE INDEX "OrganizationLicense_organizationId_idx" ON "OrganizationLicense"("organizationId");
CREATE INDEX "Program_organizationId_status_idx" ON "Program"("organizationId","status");
CREATE UNIQUE INDEX "Program_organizationId_code_key" ON "Program"("organizationId","code");
CREATE INDEX "Location_organizationId_status_idx" ON "Location"("organizationId","status");
CREATE INDEX "Location_organizationId_programId_idx" ON "Location"("organizationId","programId");
